"""Starter content for the career preparation feature.

This is a small, reviewable starter set (five days per role) meant to be
extended by administrators in the Django admin. The questions are written in
the style of realistic interview scenarios; they are not claimed to come from
any specific interviewer or company.
"""


def q(skill, difficulty, topic, scenario, text, options, correct, explanation):
    """Build a question dict. ``correct`` is the index of the right option."""
    return {
        'skill': skill, 'difficulty': difficulty, 'topic': topic, 'scenario': scenario,
        'text': text, 'options': options, 'correct': correct, 'explanation': explanation,
    }


def day(title, objectives, topics, questions):
    return {'title': title, 'objectives': objectives, 'topics': topics, 'questions': questions}


